// frontend/src/pages/Menu.js

import React, { useEffect, useState } from "react";
import api from "../services/api";

export default function Menu({ onAddToCart }) {
  const [products, setProducts] = useState([]);

  useEffect(() => {
    api
      .get("/products")
      .then((res) => setProducts(res.data))
      .catch((err) => console.error("Eroare la încărcare produse:", err));
  }, []);

  // Grupați produsele după categorie
  const groupedByCategory = products.reduce((acc, product) => {
    const cat = product.Category || "Altele";
    if (!acc[cat]) {
      acc[cat] = [];
    }
    acc[cat].push(product);
    return acc;
  }, {});

  // Dacă vreți o ordine fixă a categoriilor, puteți defini manual:
  const categoryOrder = [
    "Pizza",
    "Burger",
    "Salad",
    "Ciorba",
    "Paste",
    "Traditional",
    "Desert",
    "Racoritoare",
  ];

  // Array cu categoriile în ordinea dorită. Dacă lipsesc în categoryOrder, le afișăm la urmă alfabetic.
  const allCategories = [
    ...categoryOrder.filter((c) => groupedByCategory[c]),
    ...Object.keys(groupedByCategory)
      .filter((c) => !categoryOrder.includes(c))
      .sort(),
  ];

  return (
    <div style={{ padding: "0 20px" }}>
      {allCategories.map((category) => (
        <div key={category} style={{ marginBottom: "40px" }}>
          {/* Titlu categorie */}
          <h2 style={{ textAlign: "center", margin: "20px 0" }}>
            {category}
          </h2>

          {/* Container produse pentru categoria respectivă */}
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              justifyContent: "center",
              gap: "20px",
            }}
          >
            {groupedByCategory[category].map((p) => (
              <div
                key={p.ProductId}
                style={{
                  border: "1px solid #ccc",
                  borderRadius: 4,
                  padding: "10px",
                  width: "200px",
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "space-between",
                  backgroundColor: "#fff",
                }}
              >
                {/* Imaginea produsului (preluată direct din ImageUrl) */}
                {p.ImageUrl ? (
                  <img
                    src={p.ImageUrl}
                    alt={p.Name}
                    style={{
                      width: "100%",
                      height: 120,
                      objectFit: "cover",
                      borderRadius: 4,
                      marginBottom: 8,
                    }}
                  />
                ) : (
                  <div
                    style={{
                      width: "100%",
                      height: 120,
                      backgroundColor: "#f0f0f0",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      color: "#888",
                      marginBottom: 8,
                    }}
                  >
                    (fără poză)
                  </div>
                )}

                {/* Numele, descrierea și prețul */}
                <div style={{ flexGrow: 1 }}>
                  <h3
                    style={{
                      margin: "0 0 8px",
                      textAlign: "center",
                      fontSize: "1.1em",
                    }}
                  >
                    {p.Name}
                  </h3>
                  <p style={{ margin: "0 0 8px", fontSize: "0.9em" }}>
                    {p.Description}
                  </p>
                  <p style={{ margin: "0 0 12px", fontWeight: "bold" }}>
                    {p.Price} lei
                  </p>
                </div>

                {/* Butonul Adaugă în coș */}
                <button
                  onClick={() =>
                    onAddToCart({
                      productId:    p.ProductId,
                      name:         p.Name,
                      description:  p.Description,
                      imageUrl:     p.ImageUrl,
                      quantity:     1,
                      pricePerUnit: p.Price,
                    })
                  }
                  disabled={!p.IsAvailable}
                  style={{
                    padding: "8px",
                    borderRadius: 4,
                    cursor: p.IsAvailable ? "pointer" : "not-allowed",
                    backgroundColor: p.IsAvailable ? "#ffcc00" : "#ccc",
                    color: "#000",
                    border: "none",
                    marginTop: 8,
                    fontWeight: "bold",
                  }}
                >
                  {p.IsAvailable ? "Adaugă în coș" : "Indisponibil"}
                </button>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}
